        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Amount must be greater than zero.")

        if payer not in self._balances:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            parts = self.members[:]
        else:
            parts = list(participants)

        if not parts:
            raise ValueError("Participants list cannot be empty.")

        for p in parts:
            if p not in self._balances:
                raise ValueError(f"Participant '{p}' is not a group member.")

        total_cents = round(amount * 100)
        n = len(parts)

        # Base share per participant in cents (rounded down to whole cents)
        base_share = total_cents // n

        # Every participant other than the payer owes base_share.
        # The payer pays for total_cents upfront, and their net contribution
        # absorbs any remainder cents if they are part of the expense.
        for p in parts:
            if p != payer:
                self._balances[p] -= base_share
                self._balances[payer] += base_share

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {member: self._balances[member] / 100.0 for member in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Debtors owe money (balance < 0), Creditors are owed money (balance > 0)
        debtors: list[list] = []
        creditors: list[list] = []

        for member, cents in self._balances.items():
            if cents < 0:
                debtors.append([member, -cents])
            elif cents > 0:
                creditors.append([member, cents])

        payments: list[tuple[str, str, float]] = []

        d_idx = 0
        c_idx = 0

        # Standard two-pointer greedy settling guarantees at most (N - 1) transactions.
        while d_idx < len(debtors) and c_idx < len(creditors):
            debtor, d_cents = debtors[d_idx]
            creditor, c_cents = creditors[c_idx]

            transfer_cents = min(d_cents, c_cents)

            # Rule 6: debts/payments smaller than 1.00 (100 cents) are written off
            if transfer_cents >= 100:
                payments.append((debtor, creditor, transfer_cents / 100.0))

            debtors[d_idx][1] -= transfer_cents
            creditors[c_idx][1] -= transfer_cents

            if debtors[d_idx][1] == 0:
                d_idx += 1
            if creditors[c_idx][1] == 0:
                c_idx += 1

        return payments
